// @vitest-environment jsdom
import { act, cleanup, fireEvent, render, screen } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { afterEach, describe, expect, it, vi } from 'vitest';
import { CopyButton, Field, Mono, Notice, SafeText, downloadBlob, downloadText } from './Common';

afterEach(() => {
  cleanup();
  vi.useRealTimers();
  vi.restoreAllMocks();
});

describe('shared presentation helpers', () => {
  it.each([
    ['info', 'Note', 'note'],
    ['warn', 'Warning', 'note'],
    ['error', 'Problem', 'alert'],
    ['ok', 'Done', 'note'],
  ] as const)('renders the %s notice with an overridable title', (kind, fallbackTitle, role) => {
    const { rerender } = render(<Notice kind={kind}>Message body</Notice>);
    expect(screen.getByRole(role).textContent).toContain(fallbackTitle);
    expect(screen.getByRole(role).textContent).toContain('Message body');
    rerender(<Notice kind={kind} title="Custom title">Updated body</Notice>);
    expect(screen.getByRole(role).textContent).toContain('Custom title');
    expect(screen.queryByText(fallbackTitle)).toBeNull();
  });

  it('connects field labels and optional hints to the supplied control', () => {
    const { rerender } = render(<Field label="RPC URL" hint="Use HTTPS">{(id, describedBy) => <input id={id} aria-describedby={describedBy} />}</Field>);
    const input = screen.getByLabelText('RPC URL');
    expect(input.getAttribute('aria-describedby')).toBeTruthy();
    expect(screen.getByText('Use HTTPS').id).toBe(input.getAttribute('aria-describedby'));
    rerender(<Field label="Amount">{(id, describedBy) => <input id={id} aria-describedby={describedBy} />}</Field>);
    expect(screen.getByLabelText('Amount').getAttribute('aria-describedby')).toBeNull();
  });

  it('reports successful and failed clipboard writes', async () => {
    const writeText = vi.fn().mockResolvedValue(undefined);
    const user = userEvent.setup();
    Object.defineProperty(navigator, 'clipboard', { configurable: true, value: { writeText } });
    const { rerender } = render(<CopyButton text="local value" label="Copy value" />);
    await user.click(screen.getByRole('button', { name: 'Copy value' }));
    expect(writeText).toHaveBeenCalledWith('local value');
    expect(await screen.findByRole('button', { name: 'Copied' })).toBeTruthy();

    writeText.mockRejectedValueOnce(new Error('clipboard unavailable'));
    rerender(<CopyButton key="retry" text="second value" label="Copy again" />);
    await user.click(screen.getByRole('button', { name: 'Copy again' }));
    expect(await screen.findByRole('button', { name: 'Copy failed: select the text manually' })).toBeTruthy();
  });

  it('protects an explicitly opted-in sensitive copy without changing default copy behavior', async () => {
    vi.useFakeTimers();
    let value = '';
    const readText = vi.fn(async () => value);
    const writeText = vi.fn(async (text: string) => { value = text; });
    Object.defineProperty(navigator, 'clipboard', { configurable: true, value: { readText, writeText } });
    const { rerender } = render(<CopyButton text="sensitive value" label="Copy secret" autoClearAfterMs={30_000} />);
    fireEvent.click(screen.getByRole('button', { name: 'Copy secret' }));
    await act(async () => { await Promise.resolve(); });
    expect(value).toBe('sensitive value');
    await act(async () => { await vi.advanceTimersByTimeAsync(30_000); });
    expect(value).toBe('');
    expect(readText).toHaveBeenCalledTimes(2);

    rerender(<CopyButton text="another value" label="Copy ordinary" />);
    fireEvent.click(screen.getByRole('button', { name: 'Copy ordinary' }));
    await act(async () => { await Promise.resolve(); });
    await act(async () => { await vi.advanceTimersByTimeAsync(5 * 60_000); });
    expect(value).toBe('another value');
  });

  it('starts a local text download and revokes the object URL', () => {
    const blob = vi.spyOn(URL, 'createObjectURL').mockReturnValue('blob:local');
    const revoke = vi.spyOn(URL, 'revokeObjectURL').mockImplementation(() => undefined);
    let clicked: { href: string; download: string; rel: string; connected: boolean } | undefined;
    const click = vi.spyOn(HTMLAnchorElement.prototype, 'click').mockImplementation(function (this: HTMLAnchorElement) {
      clicked = { href: this.href, download: this.download, rel: this.rel, connected: this.isConnected };
    });
    vi.useFakeTimers();
    downloadText('receipt.json', '{"ok":true}', 'application/json');
    expect(blob).toHaveBeenCalledOnce();
    expect(clicked).toEqual({ href: 'blob:local', download: 'receipt.json', rel: 'noopener', connected: true });
    expect(click).toHaveBeenCalledOnce();
    expect(document.querySelector('a[download="receipt.json"]')).toBeNull();
    expect(revoke).not.toHaveBeenCalled();
    vi.advanceTimersByTime(999);
    expect(revoke).not.toHaveBeenCalled();
    vi.advanceTimersByTime(1);
    expect(revoke).toHaveBeenCalledExactlyOnceWith('blob:local');
    vi.useRealTimers();
  });

  it('cleans up the temporary download anchor and Blob URL when browser click throws', () => {
    const blob = vi.spyOn(URL, 'createObjectURL').mockReturnValue('blob:blocked');
    const revoke = vi.spyOn(URL, 'revokeObjectURL').mockImplementation(() => undefined);
    const blocked = new Error('download blocked');
    vi.spyOn(HTMLAnchorElement.prototype, 'click').mockImplementation(() => { throw blocked; });

    expect(() => downloadText('blocked-receipt.json', '{"test":true}', 'application/json')).toThrow(blocked);
    expect(blob).toHaveBeenCalledOnce();
    expect(document.querySelector('a[download="blocked-receipt.json"]')).toBeNull();
    expect(revoke).toHaveBeenCalledExactlyOnceWith('blob:blocked');
  });

  it('revokes the Blob URL when attaching the download anchor fails', () => {
    vi.spyOn(URL, 'createObjectURL').mockReturnValue('blob:detached');
    const revoke = vi.spyOn(URL, 'revokeObjectURL').mockImplementation(() => undefined);
    const blocked = new Error('document unavailable');
    vi.spyOn(document.body, 'appendChild').mockImplementation(() => { throw blocked; });
    const click = vi.spyOn(HTMLAnchorElement.prototype, 'click');

    expect(() => downloadText('detached.json', '{}', 'application/json')).toThrow(blocked);
    expect(click).not.toHaveBeenCalled();
    expect(document.querySelector('a[download="detached.json"]')).toBeNull();
    expect(revoke).toHaveBeenCalledExactlyOnceWith('blob:detached');
  });

  it('downloads a caller-built binary Blob unchanged and revokes its URL only after the delay', () => {
    const bytes = new Blob([new Uint8Array([0, 255, 7])], { type: 'application/octet-stream' });
    const blob = vi.spyOn(URL, 'createObjectURL').mockReturnValue('blob:bytes');
    const revoke = vi.spyOn(URL, 'revokeObjectURL').mockImplementation(() => undefined);
    const click = vi.spyOn(HTMLAnchorElement.prototype, 'click').mockImplementation(() => undefined);
    vi.useFakeTimers();
    downloadBlob('archive.gpa', bytes);
    expect(blob).toHaveBeenCalledExactlyOnceWith(bytes);
    expect(click).toHaveBeenCalledOnce();
    expect(document.querySelector('a[download="archive.gpa"]')).toBeNull();
    vi.advanceTimersByTime(999);
    expect(revoke).not.toHaveBeenCalled();
    vi.advanceTimersByTime(1);
    expect(revoke).toHaveBeenCalledExactlyOnceWith('blob:bytes');
  });

  it('removes the anchor and revokes a binary Blob URL at once when the browser click throws', () => {
    const bytes = new Blob([new Uint8Array([1, 2, 3])], { type: 'application/octet-stream' });
    vi.spyOn(URL, 'createObjectURL').mockReturnValue('blob:blocked-bytes');
    const revoke = vi.spyOn(URL, 'revokeObjectURL').mockImplementation(() => undefined);
    const blocked = new Error('download blocked');
    vi.spyOn(HTMLAnchorElement.prototype, 'click').mockImplementation(() => { throw blocked; });
    vi.useFakeTimers();

    expect(() => downloadBlob('blocked.gpa', bytes)).toThrow(blocked);
    expect(document.querySelector('a[download="blocked.gpa"]')).toBeNull();
    expect(revoke).toHaveBeenCalledExactlyOnceWith('blob:blocked-bytes');
    vi.runAllTimers();
    expect(revoke).toHaveBeenCalledOnce();
  });

  it('renders sanitized text notices only when markers or mixed scripts need explanation', () => {
    const { rerender, container } = render(<SafeText value="normal text" />);
    expect(container.textContent).toBe('normal text');
    expect(container.querySelector('.hint')).toBeNull();
    rerender(<SafeText value={'pa\u202Eypal'} />);
    expect(container.textContent).toContain('hidden or direction-changing character');
    expect(container.textContent).toContain('⟨U+202E⟩');
    rerender(<SafeText value="aа" />);
    expect(container.textContent).toContain('lookalikes');
    rerender(<SafeText value={'pa\u202Eypal'} notice={false} />);
    expect(container.querySelector('.hint')).toBeNull();
  });

  it('renders monospace children as content', () => {
    render(<Mono>0xabc</Mono>);
    expect(screen.getByText('0xabc').tagName).toBe('CODE');
    expect(screen.getByText('0xabc').className).toContain('mono');
  });
});

describe('CopyButton localization', () => {
  it('shows the copy outcome in the active language (catalog draft) and English without a provider', async () => {
    const { I18nProvider } = await import('../i18n/context');
    const es = (await import('../../locales/es.json')).default as { messages: Record<string, string> };
    const user = userEvent.setup();
    Object.defineProperty(navigator, 'clipboard', { configurable: true, value: { writeText: () => Promise.reject(new Error('denied')) } });
    render(<I18nProvider initialPreference="es" target={document.documentElement}><CopyButton text="x" label="Copiar" /></I18nProvider>);
    await user.click(await screen.findByRole('button', { name: 'Copiar' }));
    expect(await screen.findByRole('button', { name: es.messages['common.copy.failed'] ?? 'MISSING' })).toBeTruthy();
  });

  it('does not report a completed copy for replacement text', async () => {
    let complete: (() => void) | undefined;
    const pending = new Promise<void>((resolve) => { complete = resolve; });
    const writeText = vi.fn(() => pending);
    Object.defineProperty(navigator, 'clipboard', { configurable: true, value: { writeText } });
    const { rerender } = render(<CopyButton text="first receipt" label="Copy receipt" />);
    fireEvent.click(screen.getByRole('button', { name: 'Copy receipt' }));
    rerender(<CopyButton text="second receipt" label="Copy receipt" />);
    await act(async () => { complete?.(); await pending; });
    expect(writeText).toHaveBeenCalledWith('first receipt');
    expect(screen.getByRole('button', { name: 'Copy receipt' })).toBeTruthy();
    expect(screen.queryByRole('button', { name: 'Copied' })).toBeNull();
  });

  it('clears a previous copy result when its text changes', async () => {
    const user = userEvent.setup();
    Object.defineProperty(navigator, 'clipboard', { configurable: true, value: { writeText: () => Promise.resolve() } });
    const { rerender } = render(<CopyButton text="first receipt" label="Copy receipt" />);
    await user.click(screen.getByRole('button', { name: 'Copy receipt' }));
    expect(screen.getByRole('button', { name: 'Copied' })).toBeTruthy();
    rerender(<CopyButton text="second receipt" label="Copy receipt" />);
    expect(screen.getByRole('button', { name: 'Copy receipt' })).toBeTruthy();
  });
});

import { afterEach, describe, expect, it, vi } from 'vitest';
import { recordClipboardCopy, type ClipboardPort } from './clipboardPrivacy';

afterEach(() => { vi.useRealTimers(); vi.restoreAllMocks(); });

function fakeClipboard(initial = ''): { port: ClipboardPort; value: () => string; overwrite: (next: string) => void; write: ReturnType<typeof vi.fn>; read: ReturnType<typeof vi.fn> } {
  let value = initial;
  const read = vi.fn(async () => value);
  const write = vi.fn(async (next: string) => { value = next; });
  return { port: { readText: read, writeText: write }, value: () => value, overwrite: (next) => { value = next; }, write, read };
}

describe('opt-in clipboard cleanup', () => {
  it('does not read or clear the clipboard when disabled or given an invalid delay', async () => {
    vi.useFakeTimers();
    const c = fakeClipboard('private');
    for (const delay of [0, -1, NaN, Infinity, 0.5, 5 * 60_000 + 1]) recordClipboardCopy('private', c.port, delay);
    await vi.runAllTimersAsync();
    expect(c.read).not.toHaveBeenCalled();
    expect(c.write).not.toHaveBeenCalled();
  });

  it('clears matching content only after the configured interval', async () => {
    vi.useFakeTimers();
    const c = fakeClipboard('private');
    recordClipboardCopy('private', c.port, 30_000);
    await vi.advanceTimersByTimeAsync(29_999);
    expect(c.read).not.toHaveBeenCalled();
    await vi.advanceTimersByTimeAsync(1);
    expect(c.read).toHaveBeenCalledTimes(2);
    expect(c.write).toHaveBeenCalledExactlyOnceWith('');
    expect(c.value()).toBe('');
  });

  it('never overwrites a newer external clipboard value', async () => {
    vi.useFakeTimers();
    const c = fakeClipboard('private');
    recordClipboardCopy('private', c.port, 30_000);
    c.overwrite('new text from another app');
    await vi.advanceTimersByTimeAsync(30_000);
    expect(c.read).toHaveBeenCalledOnce();
    expect(c.write).not.toHaveBeenCalled();
    expect(c.value()).toBe('new text from another app');
  });

  it('rechecks after a stale asynchronous read before clearing a newer clipboard value', async () => {
    vi.useFakeTimers();
    let value = 'private';
    let reads = 0;
    const port: ClipboardPort = {
      readText: vi.fn(async () => {
        reads += 1;
        if (reads === 1) { value = 'newer external text'; return 'private'; }
        return value;
      }),
      writeText: vi.fn(async (_text: string) => { throw new Error('Must not overwrite newer clipboard content'); }),
    };
    recordClipboardCopy('private', port, 30_000);
    await vi.advanceTimersByTimeAsync(30_000);
    expect(reads).toBe(2);
    expect(port.writeText).not.toHaveBeenCalled();
  });

  it('supersedes older timers, even when the user recopies the same text', async () => {
    vi.useFakeTimers();
    const c = fakeClipboard('private');
    recordClipboardCopy('private', c.port, 30_000);
    await vi.advanceTimersByTimeAsync(10_000);
    recordClipboardCopy('private', c.port, 30_000);
    await vi.advanceTimersByTimeAsync(20_000);
    expect(c.read).not.toHaveBeenCalled();
    await vi.advanceTimersByTimeAsync(10_000);
    expect(c.write).toHaveBeenCalledExactlyOnceWith('');
  });

  it('does not clear after a newer copy arrives while clipboard reading is pending', async () => {
    vi.useFakeTimers();
    let resolveRead: ((value: string) => void) | undefined;
    const readText = vi.fn(() => new Promise<string>((resolve) => { resolveRead = resolve; }));
    const writeText = vi.fn(async (_value: string) => undefined);
    const port: ClipboardPort = { readText, writeText };
    recordClipboardCopy('older', port, 30_000);
    await vi.advanceTimersByTimeAsync(30_000);
    expect(readText).toHaveBeenCalledOnce();
    recordClipboardCopy('newer', port, 30_000);
    if (!resolveRead) throw new Error('Expected pending clipboard read');
    resolveRead('older');
    await Promise.resolve();
    await Promise.resolve();
    expect(writeText).not.toHaveBeenCalled();
  });

  it('fails quietly when clipboard read or clear permissions are denied', async () => {
    vi.useFakeTimers();
    const readDenied: ClipboardPort = {
      readText: vi.fn(async () => { throw new Error('permission denied'); }),
      writeText: vi.fn(async (_value: string) => undefined),
    };
    recordClipboardCopy('private', readDenied, 30_000);
    await vi.advanceTimersByTimeAsync(30_000);
    expect(readDenied.writeText).not.toHaveBeenCalled();

    const writeDenied: ClipboardPort = {
      readText: vi.fn(async () => 'private'),
      writeText: vi.fn(async (_value: string) => { throw new Error('permission denied'); }),
    };
    recordClipboardCopy('private', writeDenied, 30_000);
    await expect(vi.advanceTimersByTimeAsync(30_000)).resolves.toBeUndefined();
    expect(writeDenied.writeText).toHaveBeenCalledWith('');
  });
});
